package com.acme.orders;

import java.util.List;
import java.util.Map;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

@Service
public class OrderService {

    private final OrderRepository repo;
    private final JdbcTemplate jdbc;

    public OrderService(OrderRepository repo, JdbcTemplate jdbc) {
        this.repo = repo;
        this.jdbc = jdbc;
    }

    public Order find(long id) {
        return repo.findById(id).orElseThrow(() -> new OrderNotFound(id));
    }

    public List<Map<String, Object>> lines(long id) {
        return jdbc.queryForList("SELECT sku, qty FROM order_lines WHERE order_id = ?", id);
    }
}
